import java.util.*;

public class Main {
    static long seed = 7;
    // tiny LCG so every language gets the same "random" inputs
    static int nxt() { seed = (seed * 1103515245L + 12345L) % 2147483648L; return (int) (seed >> 8); }

    static int aiMax(int[] a) {
        int best = 0;                 // BUG: should start at a[0]
        int cur = 0;
        for (int x : a) { cur = Math.max(x, cur + x); best = Math.max(best, cur); }
        return best;
    }

    static int oracleMax(int[] a) {   // tries every slice: O(n^2) but easy to trust
        int best = a[0];
        for (int i = 0; i < a.length; i++) {
            int total = 0;
            for (int j = i; j < a.length; j++) { total += a[j]; best = Math.max(best, total); }
        }
        return best;
    }

    public static void main(String[] args) {
        int mismatches = 0;
        int[] first = null;
        for (int t = 0; t < 300; t++) {
            int n = 1 + nxt() % 6;
            int[] c = new int[n];
            for (int k = 0; k < n; k++) c[k] = nxt() % 11 - 5;
            if (aiMax(c) != oracleMax(c)) { mismatches++; if (first == null) first = c; }
        }
        System.out.println("trials: 300, mismatches: " + mismatches);
        StringBuilder sb = new StringBuilder();
        for (int k = 0; k < first.length; k++) sb.append(k > 0 ? ", " : "").append(first[k]);
        System.out.println("first failing input: [" + sb + "]");
        System.out.println("ai: " + aiMax(first) + " oracle: " + oracleMax(first));
    }
}

