// tiny LCG so every language gets the same "random" inputs
int nxt() { seed = (seed * 1103515245LL + 12345LL) % 2147483648LL; return (int)(seed >> 8); }

int aiMax(const vector<int>& a) {
    int best = 0;                 // BUG: should start at a[0]
    int cur = 0;
    for (int x : a) { cur = max(x, cur + x); best = max(best, cur); }
    return best;
}

int oracleMax(const vector<int>& a) {   // tries every slice: O(n^2) but easy to trust
    int best = a[0];
    for (size_t i = 0; i < a.size(); i++) {
        int total = 0;
        for (size_t j = i; j < a.size(); j++) { total += a[j]; best = max(best, total); }
    }
    return best;
}

int main() {
    int mismatches = 0;
    vector<int> first;
    for (int t = 0; t < 300; t++) {
        int n = 1 + nxt() % 6;
        vector<int> c;
        for (int k = 0; k < n; k++) c.push_back(nxt() % 11 - 5);
        if (aiMax(c) != oracleMax(c)) { mismatches++; if (first.empty()) first = c; }
    }
    cout << "trials: 300, mismatches: " << mismatches << "\n";
