class Program
{
    static long seed = 7;
    // tiny LCG so every language gets the same "random" inputs
    static int Nxt() { seed = (seed * 1103515245L + 12345L) % 2147483648L; return (int)(seed >> 8); }

    static int AiMax(int[] a)
    {
        int best = 0;                 // BUG: should start at a[0]
        int cur = 0;
        foreach (int x in a) { cur = Math.Max(x, cur + x); best = Math.Max(best, cur); }
        return best;
    }

    static int OracleMax(int[] a)     // tries every slice: O(n^2) but easy to trust
    {
        int best = a[0];
        for (int i = 0; i < a.Length; i++)
        {
            int total = 0;
            for (int j = i; j < a.Length; j++) { total += a[j]; best = Math.Max(best, total); }
        }
        return best;
    }

    static void Main()
    {
        int mismatches = 0;
        int[] first = null;
        for (int t = 0; t < 300; t++)
        {
            int n = 1 + Nxt() % 6;
            int[] c = new int[n];
            for (int k = 0; k < n; k++) c[k] = Nxt() % 11 - 5;
            if (AiMax(c) != OracleMax(c)) { mismatches++; if (first == null) first = c; }
        }
        Console.WriteLine("trials: 300, mismatches: " + mismatches);
        Console.WriteLine("first failing input: [" + string.Join(", ", first) + "]");
        Console.WriteLine("ai: " + AiMax(first) + " oracle: " + OracleMax(first));
    }
}

