# A typical AI-written binary search: finds A match, not the FIRST match.
def ai_search(a, target):
    lo, hi = 0, len(a) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if a[mid] == target:
            return mid                  # BUG: stops at any match
        if a[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def first_search(a, target):
    lo, hi, ans = 0, len(a) - 1, -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if a[mid] == target:
            ans = mid                   # remember it, keep looking left
            hi = mid - 1
        elif a[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return ans

def oracle(a, target):                  # simple scan: obviously correct
    return a.index(target) if target in a else -1

data = [1, 2, 2, 2, 2, 3, 4]
print("input:", data)
for t in (2, 4, 9):
    print("target", t, "-> ai:", ai_search(data, t),
          "fixed:", first_search(data, t), "oracle:", oracle(data, t))
# Both searches are O(log n) time, O(1) space; the oracle is O(n).
